std::string escapeRegex(const std::string& pattern) {
    std::string escaped;
    for (char c : pattern) {
        if (std::string("()[]{}.*+?^$|\\").find(c) != std::string::npos) {
            escaped += '\\';  // Escape special character
        }
        escaped += c;
    }
    return escaped;
}

